183:     const scout = $('#scoutTarget'); if (scout) scout.onclick = () => { if (!(state.army.Scouts > 0)) { toast('You need scouts. Train them in the barracks.'); return; } launchMarch('scout', p.name, 'Scouts', 1, p.defenders); closeModal(); };
184:     const attack = $('#attackTarget'); if (attack) attack.onclick = () => showAttack(p);
