189:     $('#launchAttack').onclick = () => { const unit = $('#attackUnit').value, count = Math.floor(+$(' #attackCount'.trim()).value); if (!count || count < 1 || count > (state.army[unit] || 0)) { toast(`You have ${state.army[unit] || 0} ${unit.toLowerCase()} ready.`); return; } state.army[unit] -= count; launchMarch('attack', p.name, unit, count, p.defenders); closeModal(); };
190:   }
191:   function launchMarch(kind, target, unit, count, defenders) {
192:     if (kind === 'scout' && (state.army.Scouts || 0) < count) { toast('You need scouts. Train them in the barracks.'); return false; }
193:     if (kind === 'scout') state.army.Scouts -= count;
194:     const duration = kind === 'scout' ? 30 : 60;
