199:   }
200:   function showVillage() {
201:     openModal(`<div class="eyebrow">YOUR HOLDFAST · MOSSWICK</div><h2>A village taking root.</h2><p>Four generations have raised this settlement from the edge of the Ironwood. Its buildings grow stronger with each order.</p><div class="modal-options">${Object.entries(state.buildings).map(([name, level]) => `<div class="option-card"><span class="option-symbol">${name === 'Timber camp' ? '⌁' : name === 'Stone quarry' ? '⬡' : name === 'Iron mine' ? '◆' : name === 'Longhouse' ? '⌂' : '▥'}</span><span class="option-copy"><b>${name}</b><small>Level ${level}${name === 'Longhouse' ? ` · ${state.population}/120 villagers` : ''}</small></span><span class="option-cost">✦</span></div>`).join('')}</div><div class="modal-note">Village production continues while you are away · Resource storage cap: 5,000 each.</div>`);
202:   }
203:   function showReports() {
204:     openModal(`<div class="eyebrow">THE CHRONICLE · ${state.reports.length} ENTRIES</div><h2>Words carried by the wind.</h2><p>Every dispatch, raid, and change in the valley is recorded here.</p><div class="modal-options">${state.reports.map(r => `<div class="option-card"><span class="option-symbol">${r.icon}</span><span class="option-copy"><b>${r.title}</b><small>${r.text}</small></span><span class="option-cost">${r.time}</span></div>`).join('')}</div>`);
205:     document.querySelector('.nav-item[data-view="reports"] .unread-dot')?.remove();
206:   }
207:   const headings = { overview: ['OVERVIEW', 'The valley remembers.'], village: ['VILLAGE', 'A village taking root.'], map: ['WORLD MAP', 'The valley beyond.'], barracks: ['BARRACKS', 'The warband awaits.'], reports: ['REPORTS', 'Words carried by the wind.'] };
208:   function navigate(view) {
209:     document.querySelectorAll('.nav-item').forEach(b => b.classList.toggle('active', b.dataset.view === view));
210:     const heading = headings[view]; $('#pageCrumb').textContent = heading[0]; $('#pageTitle').textContent = heading[1];
211:     if (view === 'village') showVillage(); if (view === 'map') { $('#mapPreview').scrollIntoView({ behavior: 'smooth', block: 'center' }); toast('Select a nearby settlement to inspect it.'); }
212:     if (view === 'barracks') showBarracks(); if (view === 'reports') showReports();
213:   }
214:   document.querySelectorAll('.nav-item').forEach(b => b.addEventListener('click', () => navigate(b.dataset.view)));
215:   document.querySelectorAll('[data-view="village"]').forEach(b => b.addEventListener('click', () => navigate('village')));
216:   document.querySelectorAll('[data-view="map"]').forEach(b => b.addEventListener('click', () => navigate('map')));
217:   document.querySelectorAll('[data-view="reports"]').forEach(b => b.addEventListener('click', () => navigate('reports')));
218:   $('#quickBuild').onclick = showBuild; $('#addOrder').onclick = showBuild; $('#villageSelect').onclick = showVillage; $('#tribeBtn').onclick = () => openModal(`<div class="eyebrow">TRIBE HALL · ALLIANCE</div><h2>The Reedbound</h2><p>“Where the river bends, the reeds hold.” Your tribe is an alliance of twelve villages sworn to keep the valley free.</p><div class="tribe-stats"><div><b>12</b><small>MEMBERS</small></div><div><b>#08</b><small>RANK</small></div><div><b>6,420</b><small>RENOWN</small></div></div><div class="modal-note">Members online: Kael Reedhand, Mara-of-the-Reeds, Alder Fenwalker, and you.</div>`);
219:   $('#notifications').onclick = () => { const m = state.marches.length; openModal(`<div class="eyebrow">MESSENGER BIRDS</div><h2>${m ? `${m} dispatch${m > 1 ? 'es' : ''} on the road.` : 'All quiet in the valley.'}</h2><p>${m ? state.marches.map(x => `${x.kind === 'scout' ? 'Scouts' : 'Warband'} returning from ${x.target} in ${Math.max(1, Math.ceil((x.returnAt - gameNow()) / 1000))} seconds.`).join('<br>') : 'Your people have no urgent messages. Check the chronicle for recent news.'}</p><button class="primary-button modal-submit" id="openReports">Read the chronicle</button>`); $('#openReports').onclick = showReports; };
220:   $('#helpBtn').onclick = () => openModal('<div class="eyebrow">FIELD GUIDE · FIRST STEPS</div><h2>Make your mark on the valley.</h2><p><b>Gather.</b> Timber, stone, and iron trickle in over time, even while you are away.<br><br><b>Build.</b> Upgrade your village through the “Build something” button. Higher production buildings increase your hourly income.<br><br><b>Recruit.</b> Train units in the Barracks, then select an enemy settlement on the map to scout or raid.<br><br><b>Belong.</b> You are one of twelve members of the Reedbound tribe. Allies are marked in green; rivals in rust.<br><br>Your game saves automatically in this browser.</p>');
